You can make FastAPI return response that follows your schema by adding an exception handler:
from typing import Literal

from fastapi import FastAPI, HTTPException
from fastapi.responses import JSONResponse
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI()


@app.exception_handler(404)
async def not_found_handler(request, exc: HTTPException):
    return JSONResponse(
        status_code=404,
        content={"code": exc.detail.get("code"), "message": exc.detail.get("message")},
    )


# custom error pydantic model that populate "detail" prop of (FastApi) HTTPException
# NOTE: this is a base class that need to be extended
class HttpExpectedError(BaseModel):
    code: str = Field(..., description="Error code like PLAYLIST_NOT_FOUND")
    message: str = Field(..., description="Error message for human")

    def toFastApiJson(self):
        return self.model_dump()


# concret error pydantic model for one route (that extends HttpExpectedError)
class HttpError_PlaylistNotFound(HttpExpectedError):
    code: Literal["PLAYLIST_NOT_FOUND"] = "PLAYLIST_NOT_FOUND"


# route
@app.get(
    path="/playlists/{playlist_id}",
    responses={404: {"model": HttpError_PlaylistNotFound}},
)
async def getOne(playlist_id: str):
    playlist = None

    if not playlist:
        raise HTTPException(
            status_code=404,
            detail=HttpError_PlaylistNotFound(
                message=f"Playlist {playlist_id} not found"
            ).toFastApiJson(),
        )


def test_404():
    client = TestClient(app)

    response = client.get("/playlists/123")
    assert response.status_code == 404
    assert response.json() == {
        "code": "PLAYLIST_NOT_FOUND",
        "message": "Playlist 123 not found",
    }
Or use generic response wrapper to add detail property to the schema in openapi:
class ErrorResponse(BaseModel, Generic[ErrorT]):
    detail: ErrorT


# route
@app.get(
    path="/playlists/{playlist_id}",
    responses={404: {"model": ErrorResponse[HttpError_PlaylistNotFound]}},
)
async def getOne(playlist_id: str):
    playlist = None

    if not playlist:
        raise HTTPException(
            status_code=404,
            detail=HttpError_PlaylistNotFound(
                message=f"Playlist {playlist_id} not found"
            ).toFastApiJson(),
        )

HTMLResponse is defined in Starlette, not FastAPI, so the __html__ support would need to live there. FastAPI's HTMLResponse is just a re-export of starlette.responses.HTMLResponse.
The current implementation passes content directly to the Response body, which calls .encode() and expects a string or bytes. There is no protocol hook for arbitrary objects.
For now the explicit workaround is to call __html__ yourself at the call site:
@app.get("/")
def root():
    return HTMLResponse(CustomHTML().__html__())
If you want to avoid spelling that out on every route, a thin subclass works:
from fastapi.responses import HTMLResponse

class SmartHTMLResponse(HTMLResponse):
    def __init__(self, content=None, **kwargs):
        if content is not None and not isinstance(content, (str, bytes)) and hasattr(content, "__html__"):
            content = content.__html__()
        super().__init__(content=content, **kwargs)
Use SmartHTMLResponse as your response_class and it transparently handles objects that implement __html__.
For upstreaming the feature, I would open the discussion or PR in the Starlette repo rather than FastAPI. The __html__ protocol is well established in the Python web ecosystem (Jinja2, MarkupSafe, Django's mark_safe) so it has a reasonable case for first-class support, but the change belongs in Starlette's Response.__init__ where the content encoding actually happens.

I think you can workaround this using Middleware that fixes the Content-Type:
from fastapi import FastAPI, Form

app = FastAPI()


class FixContentTypeMiddleware:
    def __init__(self, app):
        self.app = app

    async def __call__(self, scope, receive, send):
        if scope["type"] == "http" and scope["path"] == "/Action":
            headers = [
                (name, value)
                for name, value in scope["headers"]
                if name != b"content-type"
            ]
            headers.append((b"content-type", b"application/x-www-form-urlencoded"))
            scope = dict(scope, headers=headers)
        await self.app(scope, receive, send)


app.add_middleware(FixContentTypeMiddleware)


@app.post("/Action")
async def process(Source: str = Form(...)):
    return {"Source": Source}

